const STY = (bg) => `position:absolute;left:70px;width:800px;height:220px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border-radius:46px;box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.5);background:${bg};color:#0b1020;font-family:inherit;font-weight:800;line-height:1.1;font-size:48px;opacity:0;padding:20px;box-sizing:border-box;text-transform:uppercase;`;
const B1 = `linear-gradient(180deg,color-mix(in srgb,var(--acc) 72%,#fff),var(--acc) 55%,color-mix(in srgb,var(--acc) 84%,#000))`;
const B2 = `linear-gradient(180deg,color-mix(in srgb,var(--acc2) 72%,#fff),var(--acc2) 55%,color-mix(in srgb,var(--acc2) 84%,#000))`;

root.innerHTML = `
  <div id="c0" style="${STY(B1)}top:80px;z-index:3;">ELEVEN AGENT</div>
  <div id="c1" style="${STY(B2)}top:80px;z-index:2;">DRAFTING<br>EMAILS</div>
  <div id="c2" style="${STY(B1)}top:80px;z-index:1;">SCRIBE V3<br>ENGINE</div>
  <div id="tag" style="position:absolute;top:920px;left:0;width:940px;text-align:center;color:#ffffff;font-size:42px;font-weight:900;opacity:0;letter-spacing:2px;">NEW MODEL RELEASE</div>
  <svg style="position:absolute;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:8;stroke-linecap:round;opacity:0.2">
    <path id="l0" d="M470 300 L470 360" />
    <path id="l1" d="M470 580 L470 640" />
  </svg>
`;

const els = [root.querySelector('#c0'), root.querySelector('#c1'), root.querySelector('#c2')];
const tag = root.querySelector('#tag');
const lines = [root.querySelector('#l0'), root.querySelector('#l1')].map(el => {
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});

function frame(t, p, d) {
  const tf = Math.min(t, d * 0.55);

  // Card 0 Entrance (Master Block)
  const s0 = spr(tf, 0, 0.8, 6);
  els[0].style.opacity = s0;
  els[0].style.transform = `scale(${lerp(0.8, 1, s0)})`;

  // Card 1 Split/Stack
  const s1 = spr(tf, 1.2, 0.8, 6);
  els[1].style.opacity = s1;
  els[1].style.transform = `translateY(${lerp(0, 280, s1)}px)`;

  // Card 2 Split/Stack
  const s2 = spr(tf, 2.4, 0.8, 6);
  els[2].style.opacity = s2;
  els[2].style.transform = `translateY(${lerp(0, 560, s2)}px)`;

  // Tag and Lines
  const s3 = spr(tf, 3.2, 0.9, 5);
  tag.style.opacity = s3;
  tag.style.transform = `translateY(${lerp(20, 0, s3)}px)`;

  lines[0].el.style.strokeDashoffset = lines[0].len * (1 - spr(tf, 1.6, 0.8, 6));
  lines[1].el.style.strokeDashoffset = lines[1].len * (1 - spr(tf, 2.8, 0.8, 6));
}
